import csv

rows = list(csv.reader(open('/work/workspace/documents/bank_checking_2024-12_to_2026-01.csv')))
header, data = rows[0], rows[1:]

def classify(desc, date):
    d = desc.upper()
    if 'TESSARO' in d:
        if date == '2024-12-27':
            return ('prior_year', '', 'Received Dec 2024; cash method puts it on the 2024 return. Not in Tessaro 2025 1099-NEC (9,400 = the four 2025 credits). Confirm reported for 2024.')
        return ('business_income', '1', 'Direct ACH; 2025 credits total 9,400, matches Tessaro 1099-NEC exactly.')
    if 'PAYHUB PAYOUT' in d:
        return ('business_income', '1', 'Net payout deposited. Line 1 uses the 1099-K gross; retained PayHub fees go on line 10. Monthly deposits = 97.1% of 1099-K monthly gross (2.9% processor fee).')
    if 'LARKSPUR' in d:
        return ('other_schedule', '', 'W-2 wages (net of withholding). Gross 24,800 goes on Form 1040 line 1a, not Schedule C.')
    if 'BEACON' in d or 'ORCHARD' in d:
        return ('business_income', '1', 'No such direct bank credit exists; assumed paid through PayHub and inside the 1099-K gross - see QUESTIONS.')
    if 'HISCOX' in d:
        return ('business_expense', '15', 'Professional liability insurance (business). Per instructions excerpt, line 15.')
    if 'CAPITAL FACTORY' in d:
        return ('business_expense', '20b', 'Coworking membership rent, 350 x 8 = 2,800. Instructions excerpt allows coworking on line 20b.')
    if 'BLUE CROSS' in d:
        return ('other_schedule', '', 'Health insurance premiums (380 x 8 = 3,040). Excluded from line 15 per instructions; self-employed health insurance deduction on Schedule 1 line 17.')
    if 'FIGMA' in d:
        return ('business_expense', '27a', 'Design software subscription, 45 x 12 = 540.')
    if 'ADOBE' in d:
        return ('business_expense', '27a', 'Creative Cloud subscription, 59.99 x 12 = 719.88.')
    if 'T-MOBILE' in d:
        return ('business_expense', '25', 'Cell phone, 85 x 12 = 1,020. Business-use % NOT documented; 100% stated as assumption pending Dana answer.')
    if 'SPECTRUM' in d:
        return ('business_expense', '25', 'Internet, 70 x 12 = 840. Business-use % NOT documented; 100% stated as assumption pending Dana answer. Not basic first-line local phone service.')
    if 'MACBOOK' in d:
        return ('business_expense', '27a', 'MacBook Pro 14, 2,149, under the 2,500 per-item limit; expensed under de minimis safe harbor, Reg. 1.263(a)-1(f), election statement to be attached. 100% business use assumed.')
    if 'DESIGNWEEK' in d:
        return ('business_expense', '27a', 'Conference registration - professional development.')
    if 'SOUTHWEST AIR 526' in d or 'HOTEL ZEPHYR' in d:
        return ('business_expense', '24a', 'SF trip airfare/lodging tied to DesignWeek SF; trip assumed primarily business, pending confirmation.')
    if 'SOUTHWEST AIR 118' in d:
        return ('personal', '', 'Denver airfare with no corroborating business purpose anywhere in the file (no mileage or client entry). Excluded pending Dana answer.')
    if 'MARINA DELI' in d or 'TARTINE' in d:
        return ('business_expense', '24b', 'Meals on the SF trip; 50% limit per Pub. 463 excerpt (64 + 126 at 50% = 95 on line 24b).')
    if 'USATAXPYMT' in d:
        return ('tax_payment', '', 'Federal estimated tax (1,500 + 2,500 + 2,500 = 6,500). Federal income tax is not deductible; payments are credited on the Form 1040.')
    if 'M. OKAFOR RENT' in d:
        return ('personal', '', 'Residential rent paid to M. Okafor, 1,650 x 12 = 19,800. Personal - IRC 262(a). No home-office deduction claimed (no qualifying facts).')
    if 'NETFLIX' in d:
        return ('personal', '', 'Personal subscription.')
    if 'ORANGETHEORY' in d:
        return ('personal', '', 'Personal gym membership.')
    if 'H-E-B' in d:
        extra = ' (Dec 2024 - prior period)' if date.startswith('2024') else ''
        return ('personal', '', 'Groceries/personal debit card spending' + extra + '. Personal - IRC 262(a).')
    if 'VENMO' in d:
        return ('personal', '', 'Wedding gift. Personal - IRC 262(a).')
    return ('other', '', 'UNCLASSIFIED')

out = [['date','description','amount','classification','schedule_c_line','note']]
for date, desc, amount, bal in data:
    c, line, note = classify(desc, date)
    out.append([date, desc, amount, c, line, note])

with open('/work/workspace/deliverable/classification.csv','w',newline='') as f:
    csv.writer(f).writerows(out[1:])
print("wrote", len(out)-1, "rows")
from collections import Counter
print(Counter(r[3] for r in out[1:]))
EOF

